          "current": "}\nexport const inspectCommercialCommission=(c,receipt)=>commercialCommissionWitness(c,receipt,false);\nexport const consumeCommercialCommission=(c,receipt)=>commercialCommissionWitness(c,receipt,true);\n\nconst commissionRefundScopes=new WeakMap();\nasync function refund(c,row,customer,run){\n const token=Object.freeze({}),state={active:true,c,transaction:itemTransactionIdentity(c),commissionId:row.id,sourceHash:row.source_hash,maker:row.maker_character,customer:row.customer_character};\n commissionRefundScopes.set(token,state);try{return await refundLeaf(c,row,customer,run,token);}finally{state.active=false;commissionRefundScopes.delete(token);}\n}\nexport async function assertCommissionRefundScope(c,commissionId,token){\n assertItemTransaction(c);const s=commissionRefundScopes.get(token);if(!s?.active||s.c!==c||s.transaction!==itemTransactionIdentity(c)||s.commissionId!==commissionId)fail('refund_scope');\n const row=(await c.query('SELECT * FROM commissioned_crafting_contracts WHERE id=$1',[commissionId])).rows[0];\n if(row?.status!=='refunded'||row.source_hash!==s.sourceHash||hash(source(row))!==s.sourceHash||row.maker_character!==s.maker||row.customer_character!==s.customer||Number(row.fee_remaining)||Number(row.fee_refunded)!==Number(row.fee_total))fail('refund_source');return true;\n}\nexport async function refundProductionBookingCommissionInEstate(c,commissionId,victim,rentalScope,estateScope){\n assertItemTransaction(c);try{\n  const estate=await assertEstateResolutionScope(c,victim,estateScope),locked=await assertEquipmentRentalDeathScope(c,victim,rentalScope);\n  const row=(await c.query('SELECT * FROM commissioned_crafting_contracts WHERE id=$1 FOR UPDATE',[id(commissionId)])).rows[0];\n  const booking=(await c.query(\"SELECT * FROM production_booking_runs WHERE commission_id=$1 AND state='active'\",[commissionId])).rows[0];\n  if(!row||row.status!=='accepted'||!booking||![row.maker_character,row.customer_character].includes(victim)||!locked.ids.has(row.maker_character)||!locked.ids.has(row.customer_character)\n   ||booking.maker_character!==row.maker_character||booking.customer_character!==row.customer_character||booking.commission_source_hash!==row.source_hash||hash(source(row))!==row.source_hash)fail('death_scope');\n  const original=(await c.query('SELECT account_id,alive FROM characters WHERE id=$1',[victim])).rows[0];if(!original?.alive||original.account_id!==estate.accountId)fail('death_scope');\n  const customer=(await c.query('SELECT * FROM characters WHERE id=$1',[row.customer_character])).rows[0];return await refund(c,row,customer,'booking-estate:'+row.id);\n }catch(error){poisonItemTransaction(c,error);throw error;}\n}\n",
