          "baseline": "import {assertItemTransaction,itemTransactionIdentity,poisonItemTransaction} from './items.js';\nimport {prelockEquipmentRentalDeathActors,assertEquipmentRentalDeathScope} from './equipmentrentals.js';\nimport {DISTRICTS,CONSTANTS,jailed,safeHoused} from './rules.js';\nconst scopes=new AsyncLocalStorage(),REFERENCES=Object.freeze([\"agent_operating_memory_facts:business_id\",\"business_depot_journal:depot_id\",\"business_external_costs:depot_id\",\"business_operating_policies:depot_id\",\"business_partnerships:depot_id\",\"business_relocation_plans:depot_id\",\"business_season_entries:depot_id\",\"business_supply_contracts:depot_id\",\"business_warehouse_leases:depot_id\",\"commercial_campaigns:business_id\",\"commercial_disputes:depot_id\",\"commercial_negotiations:depot_id\",\"commercial_premises_leases:depot_id\",\"commercial_premises_offers:depot_id\",\"commissioned_crafting_contracts:business_id\",\"company_acquisitions:depot_id\",\"company_logistics_hubs:depot_id\",\"company_operator_receipts:depot_id\",\"company_operators:depot_id\",\"company_production_receipts:business_id\",\"company_restructuring_plans:depot_id\",\"company_specialization_runs:business_id\",\"company_specializations:business_id\",\"company_succession_receipts:depot_id\",\"company_workflows:depot_id\",\"contract_auctions:depot_id\",\"customer_vault_services:depot_id\",\"delivery_commitments:depot_id\",\"depot_brand_licenses:operator_depot_id\",\"depot_brand_licenses:recipient_depot_id\",\"economic_intelligence_publications:depot_id\",\"employment_organizations:depot_id\",\"equipment_recovery_requests:business_id\",\"funded_external_work_jobs:depot_id\",\"game_employment_jobs:depot_id\",\"infrastructure_concessions:business_id\",\"logistics_coverage_policies:depot_id\",\"manufacturing_licenses:licensee_business\",\"manufacturing_licenses:licensor_business\",\"market_listings:depot_id\",\"picking_packing_jobs:depot_id\",\"production_slot_reservations:business_id\",\"strategy_laboratories:business_id\",\"supply_tenders:depot_id\",\"territory_economics_profiles:business_id\",\"worker_training_courses:depot_id\",\"workshop_floor_requests:business_ref\",\"workshop_floorplans:business_id\"]);\nconst fail=reason=>{throw new GameError('business_relocation',reason);};\nconst stable=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);\nconst hash=v=>crypto.createHash('sha256').update(stable(v)).digest('hex');\n"
