          "current": "  const issues=[],rows=(await c.query('SELECT * FROM workshop_floorplans ORDER BY business_id')).rows;for(const p of rows){try{checkPlan(p);await authored(c,p);}catch{issues.push({id:p.business_id,reason:'plan_source'});}}\n  const requests=(await c.query('SELECT * FROM workshop_floor_requests ORDER BY account_id,key_hash')).rows;for(const r of requests){try{const b=terms(r.request_json),s=r.source_json;if(r.body_hash!==hash(b)||r.account_ref!==r.account_id||s.accountId!==r.account_id||s.originalCharacter!==r.original_character||s.businessId!==r.business_ref||s.revision!==b.expectedRevision+1||stable(s.allocations)!==stable(b.allocations)||r.receipt?.sourceHash!==hash(s)||r.receipt?.revision!==s.revision)fail('request');}catch{issues.push({id:r.run_id,reason:'request_binding'});}}return issues;\n}\n\n// OFFREPO fixed source reader; no production authority or caller capability.\nexport async function workshopFloorQualityBookingSource(c,ctx){\n  I.assertItemTransaction(c);const p=(await c.query('SELECT * FROM workshop_floorplans WHERE business_id=$1 FOR UPDATE',[ctx.businessId])).rows[0];\n  if(!p||p.account_id!==ctx.accountId||p.original_character!==ctx.originalCharacter)fail('booking_floor_original');\n  if(!p.allocations.some(x=>x.use==='service')||!p.allocations.some(x=>x.use==='tool_bench'))fail('booking_floor_allocations');\n  await source(c,p,{requireBench:true});\n  const profile=(await c.query('SELECT * FROM company_specializations WHERE business_id=$1 FOR UPDATE',[ctx.businessId])).rows[0],uid=p.allocations.find(x=>x.use==='tool_bench').toolItemId;\n  if(profile?.kind!=='quality'||profile.tool_item_id!==uid||profile.account_id!==ctx.accountId||profile.original_character!==ctx.originalCharacter)fail('booking_profile_original');\n  const equipment=await assertEquipmentUsable(c,{itemId:uid,owner:{scope:'account',id:ctx.accountId},minimum:80});\n  const state=(await c.query('SELECT creation_event,revision FROM item_durability_states WHERE item_id=$1',[uid])).rows[0];\n  const births=(await c.query(\"SELECT id FROM item_events WHERE item_id=$1 AND event_kind='created' ORDER BY sequence LIMIT 2\",[uid])).rows;if(births.length!==1)fail('booking_birth');\n  return{businessId:ctx.businessId,account:ctx.accountId,original:ctx.originalCharacter,profile,\n    floor:{revision:p.revision,sourceHash:p.source_hash,source:p.source_json,allocations:p.allocations},\n    equipment:{...equipment,creationEvent:births[0].id,revision:Number(state?.revision??0)}};\n}\n",
